1	import { BookingEntity, ExceptionHelper } from '@roombook/backend-common';
2	import { CreateBookingDto, ErrorCodeEnum, UpdateBookingDto } from '@roombook/contract';
3	import { INSTANT_GRAMMAR, parseInstant } from './booking-instant';
4	
5	export class NormalisedBookingDto {
6	  roomId: string;
7	  title: string;
8	  organizerEmail: string;
9	  startsAt: Date;
10	  endsAt: Date;
11	}
12	
13	export class BookingChangesDto {
14	  title?: string;
15	  startsAt?: Date;
16	  endsAt?: Date;
17	}
18	
19	const requireInstant = (field: string, value: unknown): Date =>
20	  parseInstant(value) ??
21	  ExceptionHelper.badRequest(ErrorCodeEnum.VALIDATION, `${field} must be an instant in the form ${INSTANT_GRAMMAR}`);
22	
23	export const rejectInvalidSpan = (): never =>
24	  ExceptionHelper.badRequest(ErrorCodeEnum.VALIDATION, 'endsAt must be later than startsAt');
25	
26	const requireStorableTitle = (title: unknown): string => {
27	  if (typeof title !== 'string') {
28	    return ExceptionHelper.badRequest(ErrorCodeEnum.VALIDATION, 'title must be a string');
29	  }
30	  // Postgres text cannot hold a NUL character.
31	  if (title.includes('\u0000')) {
32	    return ExceptionHelper.badRequest(ErrorCodeEnum.VALIDATION, 'title must not contain a NUL character');
33	  }
34	  return title;
35	};
36	
37	const requireSpan =(startsAt: Date, endsAt: Date): void => {
38	  if (endsAt.getTime() <= startsAt.getTime()) {
39	    rejectInvalidSpan();
40	  }
41	};
42	
43	export const normaliseCreateBooking = (body: CreateBookingDto): NormalisedBookingDto => {
44	  const startsAt = requireInstant('startsAt', body.startsAt);
45	  const endsAt = requireInstant('endsAt', body.endsAt);
46	  requireSpan(startsAt, endsAt);
47	  return {
48	    roomId: body.roomId.toLowerCase(),
49	    title: requireStorableTitle(body.title),
50	    organizerEmail: body.organizerEmail,
51	    startsAt,
52	    endsAt,
53	  };
54	};
55	
56	export const parseBookingChanges = (changes: UpdateBookingDto): BookingChangesDto => {
57	  const parsed = new BookingChangesDto();
58	  if (changes.title !== undefined) {
59	    parsed.title = requireStorableTitle(changes.title);
60	  }
61	  if (changes.startsAt !== undefined) {
62	    parsed.startsAt = requireInstant('startsAt', changes.startsAt);
63	  }
64	  if (changes.endsAt !== undefined) {
65	    parsed.endsAt = requireInstant('endsAt', changes.endsAt);
66	  }
67	  return parsed;
68	};
69	
70	export const mergeBookingChanges = (stored: BookingEntity, changes: BookingChangesDto): BookingChangesDto => {
71	  const startsAt = changes.startsAt ?? stored.startsAt;
72	  const endsAt = changes.endsAt ?? stored.endsAt;
73	  requireSpan(startsAt, endsAt);
74	  const changed = new BookingChangesDto();
75	  if (changes.title !== undefined && changes.title !== stored.title) {
76	    changed.title = changes.title;
77	  }
78	  if (startsAt.getTime() !== stored.startsAt.getTime()) {
79	    changed.startsAt = startsAt;
80	  }
81	  if (endsAt.getTime() !== stored.endsAt.getTime()) {
82	    changed.endsAt = endsAt;
83	  }
84	  return changed;
85	};
