1	import { RpcException } from '@nestjs/microservices';
2	import { BookingEntity, IdempotencyKeyEntity } from '@roombook/backend-common';
3	import { ConfirmationStatusEnum, CreateBookingDto, ErrorCodeEnum } from '@roombook/contract';
4	import { randomUUID } from 'crypto';
5	import { DataSource, In } from 'typeorm';
6	import { bookingFingerprint } from './booking-fingerprint';
