132	    await expect(record(SENT, 3)).resolves.toMatchObject({ confirmationStatus: SENT, confirmationAttempts: 3 });
133	    await expect(record(PENDING, 3)).resolves.toMatchObject({ confirmationStatus: SENT, confirmationAttempts: 3 });
134	    await expect(record(SENT, 3)).resolves.toMatchObject({ confirmationStatus: SENT, confirmationAttempts: 3 });
