147	    const roomId = randomUUID();
148	    for (const hour of ['11', '09', '10']) {
149	      await createBooking({ roomId, startsAt: `2030-01-07T${hour}:00:00Z`, endsAt: `2030-01-07T${hour}:30:00Z` });
150	    }
151	
152	    const second = await bookings.findPage({ page: 2, limit: 2, roomId });
153	    const pastTheEnd = await bookings.findPage({ page: 5, limit: 2, roomId });
154	
155	    expect(second.items.map((item) => item.startsAt)).toEqual(['2030-01-07T11:00:00.000Z']);
156	    expect(second).toMatchObject({ total: 3, page: 2, limit: 2 });
157	    expect(pastTheEnd).toEqual({ items: [], total: 3, page: 5, limit: 2 });
