    dataSource.query(INSERT_BOOKING, [roomId, TITLE, `2030-01-07T${startsAt}Z`, `2030-01-07T${endsAt}Z`]);
  const removeRows = (): Promise<unknown> => dataSource.query(`DELETE FROM "bookings" WHERE "title" = $1`, [TITLE]);

  beforeAll(async () => {
