    await insert(R1, '09:00:00', '10:00:00');
  });

  afterAll(async () => {
    await removeRows();
    await dataSource.destroy();
  });

  it('names the constraint EXCL_bookings_room_span (BKG-016)', () => {
    expect(BOOKINGS_ROOM_SPAN_CONSTRAINT).toBe('EXCL_bookings_room_span');
  });

  it.each([
