import { RpcException } from '@nestjs/microservices';
import { BookingEntity, IdempotencyKeyEntity } from '@roombook/backend-common';
import { BookingDto, ErrorCodeEnum } from '@roombook/contract';
import { randomUUID } from 'crypto';
import { DataSource, In } from 'typeorm';
import { bookingFingerprint } from './booking-fingerprint';
import { normaliseCreateBooking } from './booking-input';
import { BookingRepository } from './booking.repository';
import { IdempotentBookingRepository, IdempotentCreateDto } from './idempotent-booking.repository';

const describeWithDatabase = process.env['DB_HOST'] ? describe : describe.skip;

const ORGANIZER = 'booking-overlap@int-spec.example';
const OVERLAP = {
  statusCode: 409,
  errorCode: ErrorCodeEnum.BOOKING_OVERLAP,
  message: 'The room is already booked in that time span',
};
const OVERLAPPING = [
  ['09:30:00', '10:30:00'],
  ['08:00:00', '09:00:00.001'],
  ['09:15:00', '09:45:00'],
  ['08:00:00', '11:00:00'],
];
const TOUCHING = [
  ['10:00:00', '11:00:00'],
  ['08:00:00', '09:00:00'],
];
const ROUNDS = 5;

const at = (time: string): string => `2030-01-07T${time}Z`;
const instant = (time: string): Date => new Date(at(time));
const iso = (time: string): string => instant(time).toISOString();
const pause = (milliseconds: number): Promise<void> => new Promise((resolve) => setTimeout(resolve, milliseconds));
const errorOf = (work: Promise<unknown>): Promise<unknown> =>
  work.then(
    () => undefined,
    (caught: unknown) => caught,
  );
const expectOverlap = (error: unknown): void => {
  expect(error).toBeInstanceOf(RpcException);
  expect((error as RpcException).getError()).toEqual(OVERLAP);
};
const expectOneWinner = (settled: PromiseSettledResult<unknown>[]): void => {
  expect(settled.filter((result) => result.status === 'fulfilled')).toHaveLength(1);
  const reasons: unknown[] = settled.flatMap((result) => (result.status === 'rejected' ? [result.reason] : []));
  expect(reasons).toHaveLength(1);
  expectOverlap(reasons[0]);
};

describeWithDatabase('overlapping room bookings (real database)', () => {
  let dataSource: DataSource;
  let bookings: BookingRepository;
  let idempotentBookings: IdempotentBookingRepository;
  let r1: string;
  let a: BookingDto;
  const keys: string[] = [];

  const commandFor = (roomId: string, from: string, to: string, key: string = randomUUID()): IdempotentCreateDto => {
    keys.push(key);
    const booking = normaliseCreateBooking({
      roomId,
      title: 'Sprint planning',
      organizerEmail: ORGANIZER,
      startsAt: at(from),
      endsAt: at(to),
    });
    return { key, fingerprint: bookingFingerprint(booking), booking };
  };
  const create = async (roomId: string, from: string, to: string): Promise<BookingDto> => {
    const outcome = await idempotentBookings.create(commandFor(roomId, from, to));
    if (outcome.kind !== 'created') {
      throw new Error(`Expected a created booking, got ${outcome.kind}`);
    }
    return outcome.booking;
  };
  const roomRows = (roomId: string): Promise<number> => dataSource.getRepository(BookingEntity).countBy({ roomId });
  const keyRows = (key: string): Promise<number> => dataSource.getRepository(IdempotencyKeyEntity).countBy({ key });
  const removeRows = async (): Promise<void> => {
    await dataSource.getRepository(BookingEntity).delete({ organizerEmail: ORGANIZER });
    await dataSource.getRepository(IdempotencyKeyEntity).delete({ key: In(keys) });
  };

  beforeAll(async () => {
    dataSource = new DataSource({
      type: 'postgres',
      host: process.env['DB_HOST'],
      port: Number(process.env['DB_PORT']),
      username: process.env['DB_USERNAME'],
      password: process.env['DB_PASSWORD'],
      database: process.env['DB_DATABASE'],
      entities: [BookingEntity, IdempotencyKeyEntity],
      synchronize: false,
    });
    await dataSource.initialize();
    bookings = new BookingRepository(dataSource.getRepository(BookingEntity), dataSource);
    idempotentBookings = new IdempotentBookingRepository(dataSource);
    await removeRows();
  });

  beforeEach(async () => {
    r1 = randomUUID();
    a = await create(r1, '09:00:00', '10:00:00');
  });

  afterAll(async () => {
    await removeRows();
    await dataSource.destroy();
  });

  it.each(OVERLAPPING)('refuses %s to %s next to A on create and on update (BKG-012, BKG-013, BKG-014)', async (from, to) => {
    const b = await create(r1, '14:00:00', '15:00:00');
    const command = commandFor(r1, from, to);

    expectOverlap(await errorOf(idempotentBookings.create(command)));
    expectOverlap(await errorOf(bookings.update(b.id, { startsAt: instant(from), endsAt: instant(to) })));

    expect(await roomRows(r1)).toBe(2);
    expect(await keyRows(command.key)).toBe(0);
    await expect(bookings.findById(b.id)).resolves.toEqual(b);
  });

  it('stores touching spans and the same span in another room on create and on update (BKG-012, BKG-013)', async () => {
    for (const [from, to] of TOUCHING) {
      const created = await create(r1, from, to);
      await bookings.deleteById(created.id);
    }
    await expect(create(randomUUID(), '09:00:00', '10:00:00')).resolves.toMatchObject({ startsAt: a.startsAt });
    const b = await create(r1, '14:00:00', '15:00:00');
    for (const [from, to] of TOUCHING) {
      await expect(bookings.update(b.id, { startsAt: instant(from), endsAt: instant(to) })).resolves.toMatchObject({
        startsAt: iso(from),
        endsAt: iso(to),
      });
    }
  });

  it('refuses B moved one millisecond into A, never A against itself, and allows touching patches (BKG-014)', async () => {
    const b = await create(r1, '10:00:00', '11:00:00');

    expectOverlap(await errorOf(bookings.update(b.id, { startsAt: instant('09:59:59.999') })));
    await expect(bookings.findById(b.id)).resolves.toEqual(b);

    await expect(bookings.update(a.id, { title: 'Retro' })).resolves.toMatchObject({ title: 'Retro' });
    await expect(bookings.update(a.id, { endsAt: instant('09:30:00') })).resolves.toMatchObject({
      endsAt: iso('09:30:00'),
    });
    await expect(bookings.update(b.id, { endsAt: instant('12:00:00') })).resolves.toMatchObject({
      endsAt: iso('12:00:00'),
    });
    await expect(bookings.update(a.id, { startsAt: instant('08:00:00') })).resolves.toMatchObject({
      startsAt: iso('08:00:00'),
    });
  });

  it('lets exactly one of two simultaneous overlapping creates win (BKG-015, R-09)', async () => {
    for (let round = 0; round < ROUNDS; round += 1) {
      const r2 = randomUUID();
      const settled = await Promise.allSettled([
        idempotentBookings.create(commandFor(r2, '09:00:00', '10:00:00')),
        idempotentBookings.create(commandFor(r2, '09:30:00', '10:30:00')),
      ]);

      expectOneWinner(settled);
      expect(settled).toContainEqual(expect.objectContaining({ value: expect.objectContaining({ kind: 'created' }) }));
      expect(await roomRows(r2)).toBe(1);
    }
  });

  it('lets exactly one of two simultaneous updates into each other win (BKG-015, R-09)', async () => {
    const c = await create(r1, '11:00:00', '12:00:00');
    for (let round = 0; round < ROUNDS; round += 1) {
      const settled = await Promise.allSettled([
        bookings.update(a.id, { endsAt: instant('10:45:00') }),
        bookings.update(c.id, { startsAt: instant('10:15:00') }),
      ]);

      expectOneWinner(settled);
      const [first, second] = [await bookings.findById(a.id), await bookings.findById(c.id)];
      expect(Date.parse(String(first?.endsAt))).toBeLessThanOrEqual(Date.parse(String(second?.startsAt)));
      await bookings.update(a.id, { endsAt: instant('10:00:00') });
      await bookings.update(c.id, { startsAt: instant('11:00:00') });
    }
  });

  it('keeps both simultaneous partial span updates, checked as the merged span (BKG-014, R-02)', async () => {
    await create(r1, '10:30:00', '11:30:00');

    await Promise.all([
      bookings.update(a.id, { startsAt: instant('08:30:00') }),
      bookings.update(a.id, { endsAt: instant('10:30:00') }),
    ]);

    await expect(bookings.findById(a.id)).resolves.toMatchObject({
      startsAt: iso('08:30:00'),
      endsAt: iso('10:30:00'),
    });
    expectOverlap(await errorOf(bookings.update(a.id, { endsAt: instant('10:30:00.001') })));
  });

  it('replays the request that created a booking instead of refusing it (BKG-013, IDM-003)', async () => {
    const command = commandFor(randomUUID(), '09:00:00', '10:00:00');
    const first = await idempotentBookings.create(command);

    await expect(idempotentBookings.create(command)).resolves.toEqual({ ...first, kind: 'replayed' });
  });

  it('stores nothing against the key of a refused create, so the key works once A is gone (IDM-007)', async () => {
    const command = commandFor(r1, '09:30:00', '10:30:00');

    expectOverlap(await errorOf(idempotentBookings.create(command)));
    expect(await keyRows(command.key)).toBe(0);
    await bookings.deleteById(a.id);

    await expect(idempotentBookings.create(command)).resolves.toMatchObject({ kind: 'created' });
    expect(await roomRows(r1)).toBe(1);
  });

  it('answers the same 409 when only EXCL_bookings_room_span stops the write (BKG-016, R-09)', async () => {
    const roomId = randomUUID();
    let release: () => void = () => undefined;
    const released = new Promise<void>((resolve) => (release = resolve));
    let holding: () => void = () => undefined;
    const held = new Promise<void>((resolve) => (holding = resolve));
    const holder = dataSource.transaction(async (manager) => {
      const unlocked = commandFor(roomId, '09:00:00', '10:00:00').booking;
      await manager.insert(BookingEntity, unlocked);
      holding();
      await released;
    });
    await held;
    const command = commandFor(roomId, '09:30:00', '10:30:00');

    const refused = errorOf(idempotentBookings.create(command));
    await pause(200);
    release();
    await holder;

    expectOverlap(await refused);
    expect(await roomRows(roomId)).toBe(1);
    expect(await keyRows(command.key)).toBe(0);
  });
});

import { RpcException } from '@nestjs/microservices';
import { Test } from '@nestjs/testing';
import { ExceptionHelper, NATS_CLIENT } from '@roombook/backend-common';
import { BookingDto, ConfirmationStatusEnum, CreateBookingDto, ErrorCodeEnum } from '@roombook/contract';
import { of, throwError } from 'rxjs';
import { BookingRepository } from './booking.repository';
import { BookingService } from './booking.service';
import { ConfirmationProducer } from './confirmation.producer';
import { IdempotentBookingRepository } from './idempotent-booking.repository';

const R1 = '3f0c1a52-8f0b-4c59-9a6e-1d2b7c9e4a10';
const K1 = '11111111-1111-4111-8111-111111111111';
const ID = '9d0c1a52-8f0b-4c59-9a6e-1d2b7c9e4a99';
const OVERLAP = {
  statusCode: 409,
  errorCode: ErrorCodeEnum.BOOKING_OVERLAP,
  message: 'The room is already booked in that time span',
};

const overlapping: CreateBookingDto = {
  roomId: R1,
  title: 'Sprint planning',
  organizerEmail: 'ann@example.com',
  startsAt: '2030-01-07T09:30:00.000Z',
  endsAt: '2030-01-07T10:30:00.000Z',
};

const stored: BookingDto = {
  ...overlapping,
  id: ID,
  startsAt: '2030-01-07T09:00:00.000Z',
  endsAt: '2030-01-07T10:00:00.000Z',
  confirmationStatus: ConfirmationStatusEnum.PENDING,
  confirmationAttempts: 0,
  createdAt: '2030-01-01T00:00:00.000Z',
  updatedAt: '2030-01-01T00:00:00.000Z',
};

const rejectWithOverlap = async (): Promise<never> =>
  ExceptionHelper.conflict(ErrorCodeEnum.BOOKING_OVERLAP, OVERLAP.message);

const rpcErrorOf = async (work: Promise<unknown>): Promise<unknown> => {
  const error = await work.then(
    () => undefined,
    (caught: unknown) => caught,
  );
  expect(error).toBeInstanceOf(RpcException);
  return (error as RpcException).getError();
};

describe('BookingService and the overlap rule', () => {
  let service: BookingService;
  const send = jest.fn();
  const enqueue = jest.fn();
  const create = jest.fn();
  const update = jest.fn();

  beforeEach(async () => {
    jest.resetAllMocks();
    send.mockReturnValue(of({ id: R1, name: 'Atlas', capacity: 4 }));
    const moduleRef = await Test.createTestingModule({
      providers: [
        BookingService,
        { provide: BookingRepository, useValue: { update } },
        { provide: IdempotentBookingRepository, useValue: { create } },
        { provide: ConfirmationProducer, useValue: { enqueue } },
        { provide: NATS_CLIENT, useValue: { send } },
      ],
    }).compile();
    service = moduleRef.get(BookingService);
  });

  it('BKG-013: answers 409 CONFLICT.BOOKING_OVERLAP for an overlapping create and enqueues no confirmation job', async () => {
    create.mockImplementation(rejectWithOverlap);

    await expect(rpcErrorOf(service.createBooking({ idempotencyKey: K1, booking: overlapping }))).resolves.toEqual(
      OVERLAP,
    );
    expect(create).toHaveBeenCalledTimes(1);
    expect(enqueue).not.toHaveBeenCalled();
  });

  it('BKG-013: answers 400 for an invalid span and 404 for an unknown room before any overlap check', async () => {
    create.mockImplementation(rejectWithOverlap);
    const notFound = { statusCode: 404, errorCode: ErrorCodeEnum.ROOM_NOT_FOUND, message: `Room ${R1} was not found` };

    await expect(
      rpcErrorOf(
        service.createBooking({ idempotencyKey: K1, booking: { ...overlapping, endsAt: overlapping.startsAt } }),
      ),
    ).resolves.toMatchObject({ statusCode: 400, errorCode: ErrorCodeEnum.VALIDATION });
    send.mockReturnValue(throwError(() => notFound));
    await expect(rpcErrorOf(service.createBooking({ idempotencyKey: K1, booking: overlapping }))).resolves.toEqual(
      notFound,
    );
    expect(create).not.toHaveBeenCalled();
    expect(enqueue).not.toHaveBeenCalled();
  });

  it('BKG-013: answers a replay of the creating request with its booking, not 409', async () => {
    create.mockResolvedValue({ kind: 'replayed', booking: stored });

    await expect(service.createBooking({ idempotencyKey: K1, booking: overlapping })).resolves.toEqual({
      booking: stored,
      replayed: true,
    });
  });

  it('BKG-014: answers 409 CONFLICT.BOOKING_OVERLAP for an update whose merged span overlaps another booking', async () => {
    update.mockImplementation(rejectWithOverlap);

    await expect(
      rpcErrorOf(service.updateBooking({ id: ID, changes: { startsAt: '2030-01-07T09:59:59.999Z' } })),
    ).resolves.toEqual(OVERLAP);
    expect(update).toHaveBeenCalledWith(ID, { startsAt: new Date('2030-01-07T09:59:59.999Z') });
  });

  it('BKG-014: a title-only update of a booking does not conflict with itself and answers the booking', async () => {
    const retitled = { ...stored, title: 'Retro' };
    update.mockResolvedValue(retitled);

    await expect(service.updateBooking({ id: ID, changes: { title: 'Retro' } })).resolves.toBe(retitled);
    expect(update).toHaveBeenCalledWith(ID, { title: 'Retro' });
  });
});

