    });

    it('returns null for an unknown booking', async () => {
      bookings.findOneBy.mockResolvedValue(null);

      await expect(repository.recordConfirmation({ bookingId: ID, status: SENT, attempts: 1 })).resolves.toBeNull();
    });
  });
});

