51	  async findPage(query: ListBookingsQueryDto): Promise<PagedBookingsDto> {
52	    const where = query.roomId ? { roomId: query.roomId } : {};
53	    const skip = (query.page - 1) * query.limit;
54	    // Postgres refuses an OFFSET beyond bigint; such a page is past the end.
55	    if (!Number.isSafeInteger(skip)) {
56	      return { items: [], total: await this.bookings.count({ where }), page: query.page, limit: query.limit };
57	    }
58	    const [entities, total] = await this.bookings.findAndCount({
59	      where,
60	      order: { startsAt: 'ASC', id: 'ASC' },
61	      skip,
62	      take: query.limit,
63	    });
64	    return { items: entities.map(toBookingDto), total, page: query.page, limit: query.limit };
65	  }
