77	  update(id: string, changes: BookingChangesDto): Promise<BookingDto | null> {
78	    return this.dataSource
79	      .transaction(async (manager) => {
80	        const stored = await manager.findOne(BookingEntity, { where: { id }, lock: { mode: 'pessimistic_write' } });
81	        if (!stored) {
82	          return null;
83	        }
84	        const changed = mergeBookingChanges(stored, changes);
85	        if (Object.keys(changed).length === 0) {
86	          return toBookingDto(stored);
87	        }
88	        if (changed.startsAt || changed.endsAt) {
89	          const { roomId, startsAt, endsAt } = { ...stored, ...changed };
90	          await requireFreeSpan(manager, { roomId, startsAt, endsAt, ownId: id });
91	        }
92	        await manager.update(BookingEntity, { id }, changed);
93	        return toBookingDto(await manager.findOneByOrFail(BookingEntity, { id }));
94	      })
95	      .catch(rethrowSpanViolation);
96	  }
