101	        id: result.bookingId,
102	        confirmationStatus: Not(ConfirmationStatusEnum.SENT),
103	        confirmationAttempts: LessThanOrEqual(result.attempts),
104	      },
105	      { confirmationStatus: result.status, confirmationAttempts: result.attempts },
106	    );
107	    return this.findById(result.bookingId);
108	  }
