9	export class IdempotentCreateDto {
10	  key: string;
11	  fingerprint: string;
12	  booking: NormalisedBookingDto;
13	}
14	
15	export type IdempotentCreateOutcome =
16	  | { kind: 'created'; booking: BookingDto }
17	  | { kind: 'replayed'; booking: BookingDto }
18	  | { kind: 'reused' }
19	  | { kind: 'in-progress' };
20	
21	type KeyLockRow = { obtained: boolean };
22	
23	const TRY_KEY_LOCK = 'SELECT pg_try_advisory_xact_lock(hashtextextended($1, 0)) AS "obtained"';
24	
25	@Injectable()
26	export class IdempotentBookingRepository {
27	  constructor(private readonly dataSource: DataSource) {}
28	
29	  create(command: IdempotentCreateDto): Promise<IdempotentCreateOutcome> {
30	    const key = command.key.toLowerCase();
31	    return this.dataSource
32	      .transaction(async (manager): Promise<IdempotentCreateOutcome> => {
33	        const [lock]: KeyLockRow[] = await manager.query(TRY_KEY_LOCK, [key]);
34	        if (!lock.obtained) {
35	          return { kind: 'in-progress' };
36	        }
37	        const stored = await manager.findOneBy(IdempotencyKeyEntity, { key });
38	        if (stored) {
39	          return stored.fingerprint === command.fingerprint
40	            ? { kind: 'replayed', booking: stored.responseBody }
41	            : { kind: 'reused' };
42	        }
43	        const { roomId, startsAt, endsAt } = command.booking;
44	        await requireFreeSpan(manager, { roomId, startsAt, endsAt });
45	        const entity = await manager.save(BookingEntity, {
46	          ...command.booking,
47	          confirmationStatus: ConfirmationStatusEnum.PENDING,
48	          confirmationAttempts: 0,
49	        });
50	        const booking = toBookingDto(entity);
51	        await manager.insert(IdempotencyKeyEntity, { key, fingerprint: command.fingerprint, responseBody: booking });
52	        return { kind: 'created', booking };
53	      })
54	      .catch(
55	        (error: unknown): IdempotentCreateOutcome =>
56	          violatedConstraint(error) === IDEMPOTENCY_KEYS_PRIMARY_KEY
57	            ? { kind: 'in-progress' }
58	            : rethrowSpanViolation(error),
59	      );
60	  }
61	}
